    # Evaluate base variable at initial time
    base_eval_shape = base_var.shape
    base_eval_size = base_var.size

    # Safely discover mesh/domain/secondary_mesh by traversing the expression tree.
    mesh = getattr(base_var, "mesh", None)
    domain = getattr(base_var, "domain", [])
    secondary_mesh = getattr(base_var, "secondary_mesh", None)

    if mesh is None or secondary_mesh is None or not domain:
        # Walk the tree to find a symbol that carries mesh information
        try:
            iterator = base_var.pre_order()
        except Exception:
            iterator = []
        for node in iterator:
            m = getattr(node, "mesh", None)
            if m is not None:
                mesh = m
                domain = getattr(node, "domain", [])
                secondary_mesh = getattr(node, "secondary_mesh", None)
                # Found sufficient information to classify dimensionality
                break

    # handle 2D (in space) finite element variables differently
    if (
        mesh is not None
        and isinstance(mesh, pybamm.ScikitSubMesh2D)
        and isinstance(domain, (list, tuple))
        and "current collector" in domain
    ):
        return ProcessedVariable2DSciKitFEM(base_variables, *args, **kwargs)

    # check variable shape; 0D or time-only variables
    if len(base_eval_shape) == 0 or base_eval_shape[0] == 1:
        return ProcessedVariable0D(base_variables, *args, **kwargs)

    # If no mesh information was found, treat as 0D/time-only to avoid AttributeError
    if mesh is None:
        return ProcessedVariable0D(base_variables, *args, **kwargs)

    # Try some shapes that could make the variable a 1D variable
    n = mesh.npts
    base_shape = base_eval_shape[0]
    if base_shape in [n, n + 1]:
        return ProcessedVariable1D(base_variables, *args, **kwargs)

    # Try some shapes that could make the variable a 2D variable
    try:
        first_dim_nodes = mesh.nodes
        first_dim_edges = mesh.edges
        second_dim_nodes = None
        if secondary_mesh is None:
            secondary_mesh = getattr(base_var, "secondary_mesh", None)
        if secondary_mesh is not None:
            second_dim_nodes = secondary_mesh.nodes
        if second_dim_nodes is not None and (
            base_eval_size // len(second_dim_nodes)
            in [len(first_dim_nodes), len(first_dim_edges)]
        ):
            return ProcessedVariable2D(base_variables, *args, **kwargs)
    except AttributeError:
        # Missing attributes imply not a standard 1D/2D spatial variable
        pass

    # Raise error for 3D or unrecognized variable shapes
    raise NotImplementedError(
        f"Shape not recognized for {base_var}"
        + "(note processing of 3D variables is not yet implemented)"
    )

